Translate the following GNU C++11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

int readInt() {
    int x; cin >> x; return x;
}
string readString() {
    string s; cin >> s; return s;
}

struct Edge {
    int from, to, capacity, flow;
};

vector<Edge> edges;
vector<int> graph[100000];
int dist1[31][31], dist2[31][31];
int dx[] = {0, 0, -1, 1};
int dy[] = {1, -1, 0, 0};
int n, t;
string a[30], b[30];
int whereX, whereY;
int source, sink;
int di[100000], ptr[100000], q[100000];

void addEdge(int u, int v, int cap) {
    edges.push_back({u, v, cap, 0});
    graph[u].push_back((int)edges.size() - 1);
    edges.push_back({v, u, 0, 0});
    graph[v].push_back((int)edges.size() - 1);
}

bool isValid(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < n;
}

void BFS1(int x = 0, int y = 0) {
    queue<pair<int,int>> q;
    q.push({x, y});
    for (int i = 0; i <= 20; ++i)
        for (int j = 0; j <= 20; ++j)
            dist1[i][j] = 1e9;
    dist1[x][y] = 0;
    while (!q.empty()) {
        auto [cx, cy] = q.front(); q.pop();
        for (int i = 0; i < 4; ++i) {
            int nx = cx + dx[i], ny = cy + dy[i];
            if (isValid(nx, ny) && dist1[nx][ny] >= 1e9 && b[nx][ny] != 'Y') {
                dist1[nx][ny] = dist1[cx][cy] + 1;
                q.push({nx, ny});
            }
        }
    }
}

bool bfs() {
    memset(di, -1, sizeof(di));
    int head = 0, tail = 0;
    q[tail++] = source;
    di[source] = 0;
    while (head < tail && di[sink] == -1) {
        int v = q[head++];
        for (int id : graph[v]) {
            int to = edges[id].to;
            if (di[to] == -1 && edges[id].flow < edges[id].capacity) {
                di[to] = di[v] + 1;
                q[tail++] = to;
            }
        }
    }
    return di[sink] != -1;
}

int dfs(int v, int flow) {
    if (flow == 0) return 0;
    if (v == sink) return flow;
    for (int &i = ptr[v]; i < (int)graph[v].size(); ++i) {
        int id = graph[v][i];
        int to = edges[id].to;
        if (di[to] != di[v] + 1) continue;
        int pushed = dfs(to, min(flow, edges[id].capacity - edges[id].flow));
        if (pushed > 0) {
            edges[id].flow += pushed;
            edges[id ^ 1].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int maxFlow() {
    int totalFlow = 0;
    while (bfs()) {
        for (int i = 0; i < (int)edges.size(); ++i)
            ptr[i] = 0;
        while (int pushed = dfs(source, 1e9))
            totalFlow += pushed;
    }
    return totalFlow;
}

void BFS2(int x, int y) {
    queue<pair<int,int>> q;
    q.push({x, y});
    for (int i = 0; i <= 20; ++i)
        for (int j = 0; j <= 20; ++j)
            dist2[i][j] = 1e9;
    dist2[x][y] = 0;
    while (!q.empty()) {
        auto [cx, cy] = q.front(); q.pop();
        if (dist2[cx][cy] >= dist1[cx][cy]) continue;
        for (int i = 0; i < 4; ++i) {
            int nx = cx + dx[i], ny = cy + dy[i];
            if (isValid(nx, ny) && dist2[nx][ny] >= 1e9 && a[nx][ny] != 'Y' && dist2[cx][cy] + 1 <= dist1[nx][ny]) {
                dist2[nx][ny] = dist2[cx][cy] + 1;
                q.push({nx, ny});
            }
        }
    }
}

int main() {
    n = readInt(); t = readInt();
    for (int i = 0; i < n; ++i) a[i] = readString();
    for (int i = 0; i < n; ++i) {
        b[i] = readString();
        for (int j = 0; j < n; ++j) {
            if (b[i][j] == 'Z') {
                b[i][j] = 'Y'; a[i][j] = 'Y';
                whereX = i; whereY = j;
            }
        }
    }
    BFS1();
    source = 0; sink = 2 * n * n + 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (a[i][j] == 'Y') continue;
            int inNode = i * n + j + 1;
            int outNode = n * n + i * n + j + 1;
            addEdge(source, inNode, a[i][j] - '0');
            addEdge(outNode, sink, b[i][j] - '0');
            BFS2(i, j);
            for (int ptx = 0; ptx < n; ++ptx) {
                for (int pty = 0; pty < n; ++pty) {
                    if (b[ptx][pty] == 'Y' || dist2[ptx][pty] > t) continue;
                    addEdge(inNode, n * n + ptx * n + pty + 1, a[i][j] - '0');
                }
            }
        }
    }
    cout << maxFlow() << endl;
    return 0;
}
